`timescale 1ns/1ps
module tb_debug5; localparam W=32; localparam H=12; localparam B=10; reg clk=0; always #5 clk=~clk; reg rst_n=0,vs=1,de=0; reg [7:0] gray=0; wire mv; wire [7:0] mg,mc; median5x5_video #(.H_ACTIVE(W)) dut(.clk(clk),.rst_n(rst_n),.hs_in(1),.vs_in(vs),.de_in(de),.gray_in(gray),.hs_out(),.vs_out(),.de_out(mv),.gray_out(mg),.gray_center_out(mc)); integer x,y,b,c=0; always @(posedge clk) begin #1; if(dut.candidate_q||dut.window_valid||mv) $display("t=%0t row=%0d col=%0d cq=%b wv=%b mv=%b comp=%0d",$time,y,dut.column,dut.candidate_q,dut.window_valid,mv,dut.completed_rows); if(mv)c=c+1; end initial begin repeat(4) @(negedge clk); rst_n=1; vs=0; repeat(8) @(negedge clk); vs=1; for(y=0;y<H;y=y+1) begin for(x=0;x<W;x=x+1) begin de=1; gray=x+y; @(negedge clk); end de=0; for(b=0;b<B;b=b+1) @(negedge clk); end repeat(100) @(negedge clk); $display("count=%0d",c); $finish; end endmodule
